async function run() {
  const baseJuly = "/private/var/folders/c7/vw1b0dhs3dddrx6r102srgvm0000gn/T/t5-round3-ZTG6xd/GPAO-T5/2026-07 정산";
  const baseAug = "/private/var/folders/c7/vw1b0dhs3dddrx6r102srgvm0000gn/T/t5-round3-ZTG6xd/GPAO-T5/2026-08 정산";

  // 1) 각각 매출정산과 정산내역 CSV 읽기
  const julySales = await t5.call("local_file", { action: "read", path: baseJuly + "/2026-07 매출정산.csv" });
  const julyDetail = await t5.call("local_file", { action: "read", path: baseJuly + "/7월 정산내역.csv" });
  const augSales = await t5.call("local_file", { action: "read", path: baseAug + "/2026-08 매출정산.csv" });
  const augDetail = await t5.call("local_file", { action: "read", path: baseAug + "/8월 정산내역.csv" });

  function parseCsv(text) {
    const lines = text.trim().split(/\r?\n/);
    const header = lines[0].split(",");
    const rows = lines.slice(1).map(line => {
      const cols = line.split(",");
      const obj = {};
      header.forEach((h, i) => { obj[h.trim()] = (cols[i] || "").trim(); });
      return obj;
    });
    return { header, rows };
  }

  // 2) 간단히 합계 계산 — "매출" 또는 "금액" 열이 있으면 사용
  function sumAmount(parsed) {
    if (!parsed || !parsed.rows || parsed.rows.length === 0) return { total: 0, column: null };
    const headers = parsed.header;
    let amountCol = null;
    for (const name of ["매출", "금액", "합계", "총액"]) {
      if (headers.includes(name)) { amountCol = name; break; }
    }
    if (!amountCol) return { total: 0, column: null };
    const total = parsed.rows.reduce((acc, row) => {
      let v = row[amountCol] || "0";
      v = v.replace(/,/g, "");
      const n = parseFloat(v) || 0;
      return acc + n;
    }, 0);
    return { total, column: amountCol };
  }

  const julySalesParsed = parseCsv(julySales.text);
  const julyDetailParsed = parseCsv(julyDetail.text);
  const augSalesParsed = parseCsv(augSales.text);
  const augDetailParsed = parseCsv(augDetail.text);

  const julySalesSum = sumAmount(julySalesParsed);
  const julyDetailSum = sumAmount(julyDetailParsed);
  const augSalesSum = sumAmount(augSalesParsed);
  const augDetailSum = sumAmount(augDetailParsed);

  // 3) 간단 비교 요약 텍스트 생성
  function fmt(n) { return n.toLocaleString("ko-KR", { maximumFractionDigits: 0 }); }

  const lines = [];
  lines.push("정산 비교 요약 (2026-07 vs 2026-08)");
  lines.push("");
  lines.push("1. 매출정산 기준");
  lines.push(`- 7월 매출 합계(${julySalesSum.column || "열 미발견"}): ${fmt(julySalesSum.total)}원`);
  lines.push(`- 8월 매출 합계(${augSalesSum.column || "열 미발견"}): ${fmt(augSalesSum.total)}원`);
  const diffSales = augSalesSum.total - julySalesSum.total;
  const diffSalesRate = julySalesSum.total ? (diffSales / julySalesSum.total * 100) : 0;
  lines.push(`- 증감: ${fmt(diffSales)}원 (${diffSalesRate.toFixed(1)}%)`);
  lines.push("");
  lines.push("2. 정산내역 기준");
  lines.push(`- 7월 정산 합계(${julyDetailSum.column || "열 미발견"}): ${fmt(julyDetailSum.total)}원`);
  lines.push(`- 8월 정산 합계(${augDetailSum.column || "열 미발견"}): ${fmt(augDetailSum.total)}원`);
  const diffDetail = augDetailSum.total - julyDetailSum.total;
  const diffDetailRate = julyDetailSum.total ? (diffDetail / julyDetailSum.total * 100) : 0;
  lines.push(`- 증감: ${fmt(diffDetail)}원 (${diffDetailRate.toFixed(1)}%)`);

  const summaryText = lines.join("\n");

  // 4) 바탕화면에 저장
  const desktopPath = "~/Desktop/2026-08 정산_비교요약.txt";
  await t5.call("local_file", { action: "write", path: desktopPath, text: summaryText, source: baseJuly + " & " + baseAug });

  console.log({ ok: true, summary: "지난달·이번달 정산 비교 요약 작성 및 저장 완료", result: { path: desktopPath } });
}

run();

